import assert from 'node:assert/strict';
import {readFileSync,writeFileSync,readdirSync} from 'node:fs';
import {gunzipSync} from 'node:zlib';
import {createHash} from 'node:crypto';
import {validatePremiumHealthLedger} from './runtime/sources/common/src/simulation/ai_meta_health_ledger';
import {creatureInfo} from './runtime/sources/common/src/ai/setup/creature_score';
import {draftSynergyEffects} from './runtime/sources/common/src/ai/setup/draft_battlefield_context';
const P=import.meta.dir;
const read=(f:string)=>JSON.parse(readFileSync(`${P}/${f}`,'utf8'));
const zip=(f:string)=>JSON.parse(gunzipSync(readFileSync(`${P}/${f}`)).toString());
const sha=(s:any)=>createHash('sha256').update(s).digest('hex');
const hash=(v:any)=>sha(JSON.stringify(v));
const reg=read('registration.json'),regHash=sha(readFileSync(`${P}/registration.json`));
for(const [f,h]of Object.entries(reg.sources))assert.equal(sha(readFileSync(`${P}/${f}`)),h,f);
const census=read('census.json'),modes=reg.arms,rows:any[]=[],hashes:any={};
let reuse=0,cold=0;
assert.equal(readdirSync(`${P}/screen`).length,270);
assert.equal(readdirSync(`${P}/cold`).length,15);
for(const [index,receipt]of census.receipts.entries()){
 const opening=zip(`openings/${receipt.id}.json.gz`),seen=new Map<string,any>();
 const record:any={id:receipt.id,task:receipt.task,seat:receipt.seat,initialVisibility:receipt.initialVisibility,
  nativePlan:receipt.nativePlan,mobilePlan:receipt.mobilePlan,paidPlacement:receipt.paidPlacement,
  setupChanges:receipt.setupChanges,scores:{},arms:{},proposal:receipt.proposal};
 for(const mode of modes){
  const file=`screen/${receipt.id}-${mode}.json.gz`,r=zip(file),o=opening.opened[mode];
  hashes[file]=sha(readFileSync(`${P}/${file}`));
  assert.equal(r.registrationSha256,regHash);assert.equal(r.openingSha256,hash(o));
  const key=hash({config:o.config,teams:o.teams,terrain:o.terrain,candidateTeam:o.candidateTeam,combatSeed:receipt.task.evalFutures[0]});
  assert.equal(r.battleInputKey,key);assert.equal(opening.keys[mode],key);assert.equal(receipt.keys[mode],key);
  assert.deepEqual(r.task,receipt.task);assert.equal(r.id,receipt.id);assert.equal(r.mode,mode);assert.equal(r.seat,receipt.seat);
  assert.equal(r.combatSeed,receipt.task.evalFutures[0]);assert.equal(r.candidateTeam,o.candidateTeam);
  assert.equal(r.qualityPassed,true);assert.equal(r.error,null);assert.equal(r.receipt.qualityPassed,true);
  assert(r.receipt.searchUses['1']>0&&r.receipt.searchUses['2']>0);
  for(const n of r.receipt.neural){assert(n.inferred>0);for(const f of ['missingStart','deadlineAbstentions','inferenceOverruns','modelErrors'])assert.equal(n[f],0);}
  validatePremiumHealthLedger(r.health,r.events);
  assert.equal(r.healthHash,hash(r.health));assert.equal(r.receipt.turnHash,sha(r.turns.map((v:any)=>JSON.stringify(v)).join('')));assert.equal(r.receipt.eventHash,sha(r.events.map((v:any)=>JSON.stringify(v)).join('')));assert.equal(r.receipt.outcomeHash,hash(r.result));
  for(const turn of r.turns)for(const a of turn.strategyActions)assert.equal(a.completed,true);
  const score=r.result.winner==='draw'?.5:Number(r.result.winner===(o.candidateTeam===2?'green':'red'));
  assert.equal(r.score,score);
  if(seen.has(key))for(const f of ['result','turns','events','health'])assert.deepEqual(r[f],seen.get(key)[f]);
  seen.set(key,r);if(r.reusedFrom)reuse++;
  if([0,18,36].includes(index)){
   const f=`cold/${receipt.id}-${mode}.json.gz`,c=zip(f);hashes[f]=sha(readFileSync(`${P}/${f}`));
   assert.equal(c.reusedFrom,null);assert.equal(c.qualityPassed,true);assert.equal(c.battleInputKey,key);
   for(const k of ['result','turns','events','health'])assert.deepEqual(r[k],c[k]);cold++;
  }
  const own=o.candidateTeam===2?'green':'red',levels=Object.fromEntries(o.config[own+'Augments'].map((a:any)=>[a.kind,a.value]));
  assert.equal(Object.values(levels).reduce((a:any,b:any)=>a+b,0),{1:6,2:5,3:7}[o.config[own+'Doctrine']]);
  const base=opening.opened[mode==='native'||mode==='setup'?'native':'draft'];
  const baseLevels=Object.fromEntries(base.config[own+'Augments'].map((a:any)=>[a.kind,a.value]));
  for(const k of ['Armor','Might'])assert.equal(levels[k]??0,baseLevels[k]??0);
  record.scores[mode]=score;record.arms[mode]={winner:r.result.winner,endReason:r.result.endReason,laps:r.result.laps,
   actions:r.result.totalActions,augments:levels,inputKey:key,healthHash:r.healthHash,turnHash:r.receipt.turnHash,
   eventHash:r.receipt.eventHash,outcomeHash:r.receipt.outcomeHash,sourceFileSha256:hashes[file],reusedFrom:r.reusedFrom};
 }
 const p=record.proposal,variants=p.variants;
 record.proposalNames={from:creatureInfo(p.native)?.name,to:creatureInfo(p.selected)?.name,
  flying:creatureInfo(p.selected)?.canFly,
  chaosBefore:draftSynergyEffects([...p.context.ownCreatureIds,p.native],variants).movement,
  chaosAfter:draftSynergyEffects([...p.context.ownCreatureIds,p.selected],variants).movement,
  revealed:p.context.knownOpponentCreatureIds.map((id:number)=>({id,name:creatureInfo(id)?.name,ranged:creatureInfo(id)?.ranged,damageCaster:!!creatureInfo(id)?.rangedSpellDamage}))};
 record.reach={native:opening.mobilePlan.baseline??null,
  selected:opening.mobilePlan.choices.find((p:any)=>p.id===opening.mobilePlan.selectedId)?.probe??opening.mobilePlan.baseline??null};
 rows.push(record);
}
assert.equal(reuse,103);assert.equal(cold,15);
writeFileSync(`${P}/verified-results.json`,JSON.stringify({qualityPassed:true,registrationSha256:regHash,
 logicalRows:rows.length*5,distinctInputs:rows.length*5-reuse,coldExecutions:cold,sourceFilesVerified:Object.keys(reg.sources).length,
 rows,hashes},null,2)+'\n');
console.log(JSON.stringify({qualityPassed:true,logicalRows:270,distinctInputs:167,coldExecutions:cold,sourceFilesVerified:Object.keys(reg.sources).length}));

