import assert from 'node:assert/strict';
import {readFileSync,writeFileSync} from 'node:fs';
import {createHash} from 'node:crypto';
const P=import.meta.dir,read=(f:string)=>JSON.parse(readFileSync(`${P}/${f}`,'utf8'));
const results=read('verified-results.json'),a=read('analysis.json'),b=read('bootstrap-check.json');
const comparisons=[['combined','native'],['combined','draft'],['combined','free'],['draft','native'],['setup','native']];
const groups=new Map<string,any[]>();for(const r of results.rows){const id=r.task.id;groups.set(id,[...(groups.get(id)??[]),r]);}
const values=[...groups.values()].map(rs=>comparisons.map(([x,y])=>rs.reduce((n,r)=>n+2*(r.scores[x]-r.scores[y]),0)));
assert.deepEqual(values,b.familyDifferencesQuarterPoints);
const sums=Buffer.alloc(20000*5*2),samples=Array.from({length:5},()=>[] as number[]);
for(const [row,indices]of b.indices.entries()){
 assert.equal(indices.length,27);
 const strata=new Map<string,number>();
 for(const i of indices){const r=[...groups.values()][i][0];const key=`${r.task.map}/${r.task.d1}`;strata.set(key,(strata.get(key)??0)+1);}
 assert.equal(strata.size,9);for(const n of strata.values())assert.equal(n,3);
 for(let j=0;j<5;j++){const total=indices.reduce((n:number,i:number)=>n+values[i][j],0);sums.writeInt16LE(total,(row*5+j)*2);samples[j].push(total/108*100);}
}
assert.equal(createHash('sha256').update(sums).digest('hex'),b.sampleSumSha256);
const quantile=(xs:number[],p:number)=>{const h=(xs.length-1)*p,l=Math.floor(h);return xs[l]+(xs[Math.ceil(h)]-xs[l])*(h-l)};
for(let i=0;i<5;i++){
 const key=comparisons[i].join('-'),total=values.reduce((n,v)=>n+v[i],0),check=a.contrasts[key];
 assert(Math.abs(total/108*100-check.differencePp)<1e-10);
 samples[i].sort((x,y)=>x-y);for(const [j,p]of [.005,.995].entries())assert(Math.abs(quantile(samples[i],p)-check.simultaneous95IntervalPp[j])<1e-10);
}
writeFileSync(`${P}/independent-analysis-check.json`,JSON.stringify({qualityPassed:true,
 checks:['270 raw scores independently recomputed','27 integer paired family differences','180000 balanced stratum draws','100000 integer bootstrap contrast sums','all 10 adjusted interval endpoints'],
 sampleSumSha256:b.sampleSumSha256,execution:'Bun independent from NumPy analyzer'},null,2)+'\n');
console.log('Independent integer/bootstrap verification passed');
